import os
import csv
import json
from pyscipopt import Model, quicksum

DATA_DIR = "/app/data"
SUB_DIR = "/app/submissions"
SOLUTION_PATH = os.path.join(SUB_DIR, "solution.csv")

def read_csv(name):
    with open(os.path.join(DATA_DIR, name), newline="") as f:
        return list(csv.DictReader(f))

def main():
    os.makedirs(SUB_DIR, exist_ok=True)

    with open(os.path.join(DATA_DIR, "config.json")) as f:
        cfg = json.load(f)

    w_wait = float(cfg["wait_penalty_per_slot_priority"])
    w_np = float(cfg["nonpreferred_provider_penalty"])
    w_ip = float(cfg["in_person_mode_penalty"])
    w_th = float(cfg["telehealth_mode_penalty"])

    providers = read_csv("providers.csv")
    slots = read_csv("slots.csv")
    appt_types = read_csv("appointment_types.csv")
    patients = read_csv("patients.csv")
    avail_rows = read_csv("provider_availability.csv")

    prov_info = {}
    for r in providers:
        prov_info[r["provider_id"]] = {
            "specialty": r["specialty"].strip(),
            "daily_slot_limit": int(r["daily_slot_limit"]),
            "telehealth_enabled": int(r["telehealth_enabled"]) == 1,
            "in_person_enabled": int(r["in_person_enabled"]) == 1,
        }

    slot_info = {}
    for r in slots:
        slot_info[r["slot_id"]] = {
            "slot_index": int(r["slot_index"]),
            "day": r["day"].strip(),
            "in_person_room_capacity": int(r["in_person_room_capacity"]),
            "telehealth_channel_capacity": int(r["telehealth_channel_capacity"]),
            "exam_room_capacity": int(r["exam_room_capacity"]),
        }
    slot_ids = [r["slot_id"] for r in slots]

    type_info = {}
    for r in appt_types:
        type_info[r["appointment_type"].strip()] = {
            "requires_exam_room": int(r["requires_exam_room"]) == 1,
            "telehealth_allowed": int(r["telehealth_allowed"]) == 1,
            "base_minutes": int(r["base_minutes"]),
        }

    pat_info = []
    for r in patients:
        pref = r["preferred_provider"].strip()
        pat_info.append({
            "patient_id": r["patient_id"].strip(),
            "specialty": r["specialty_needed"].strip(),
            "appointment_type": r["appointment_type"].strip(),
            "earliest_slot": r["earliest_slot"].strip(),
            "due_slot": r["due_slot"].strip(),
            "priority_weight": int(r["priority_weight"]),
            "allowed_modes": [m.strip() for m in r["allowed_modes"].split(";") if m.strip()] if ";" in r["allowed_modes"] else ([r["allowed_modes"].strip()] if r["allowed_modes"].strip() != "both" else ["in_person", "telehealth"]),
            "preferred_provider": pref if pref else None,
            "continuity_required": int(r["continuity_required"]) == 1,
        })

    avail = {}
    for r in avail_rows:
        avail[(r["provider_id"].strip(), r["slot_id"].strip())] = int(r["available"]) == 1

    # Build eligibility
    eligible = []  # (p_idx, v, s, m)
    cost = {}
    for pi, p in enumerate(pat_info):
        tinfo = type_info[p["appointment_type"]]
        e_idx = slot_info[p["earliest_slot"]]["slot_index"]
        u_idx = slot_info[p["due_slot"]]["slot_index"]
        for v, vinfo in prov_info.items():
            if vinfo["specialty"] != p["specialty"]:
                continue
            if p["continuity_required"] and v != p["preferred_provider"]:
                continue
            for s in slot_ids:
                sinfo = slot_info[s]
                if not (e_idx <= sinfo["slot_index"] <= u_idx):
                    continue
                if not avail.get((v, s), False):
                    continue
                for m in p["allowed_modes"]:
                    if m == "telehealth":
                        if not tinfo["telehealth_allowed"]:
                            continue
                        if not vinfo["telehealth_enabled"]:
                            continue
                    elif m == "in_person":
                        if not vinfo["in_person_enabled"]:
                            continue
                    else:
                        continue
                    c = w_wait * p["priority_weight"] * (sinfo["slot_index"] - e_idx)
                    if p["preferred_provider"] is not None and v != p["preferred_provider"]:
                        c += w_np
                    if m == "in_person":
                        c += w_ip
                    else:
                        c += w_th
                    eligible.append((pi, v, s, m))
                    cost[(pi, v, s, m)] = c

    model = Model("hybrid_telehealth_scheduling")
    model.setParam("gaprel", 0.0005)
    time_limit = 300.0
    env_limit = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if env_limit is not None:
        try:
            time_limit = min(time_limit, float(env_limit))
        except ValueError:
            pass
    model.setParam("limits/time", time_limit)

    x = {}
    for (pi, v, s, m) in eligible:
        x[(pi, v, s, m)] = model.addVar(name=f"x_{pat_info[pi]['patient_id']}_{v}_{s}_{m}", vtype="B", lb=0.0, ub=1.0, obj=0.0)

    # Patient exactly once
    for pi, p in enumerate(pat_info):
        terms = [x[k] for k in eligible if k[0] == pi]
        if not terms:
            raise RuntimeError(f"No eligible assignment for patient {p['patient_id']}")
        model.addCons(quicksum(terms) == 1, name=f"patient_{p['patient_id']}")

    # Provider-slot at most one
    prov_slot_terms = {}
    for (pi, v, s, m) in eligible:
        prov_slot_terms.setdefault((v, s), []).append(x[(pi, v, s, m)])
    for (v, s), terms in prov_slot_terms.items():
        model.addCons(quicksum(terms) <= 1, name=f"provslot_{v}_{s}")

    # Provider daily limit
    prov_day_terms = {}
    for (pi, v, s, m) in eligible:
        d = slot_info[s]["day"]
        prov_day_terms.setdefault((v, d), []).append(x[(pi, v, s, m)])
    for (v, d), terms in prov_day_terms.items():
        model.addCons(quicksum(terms) <= prov_info[v]["daily_slot_limit"], name=f"provdaily_{v}_{d}")

    # Room capacity
    ip_terms = {}
    for (pi, v, s, m) in eligible:
        if m == "in_person":
            ip_terms.setdefault(s, []).append(x[(pi, v, s, m)])
    for s, terms in ip_terms.items():
        model.addCons(quicksum(terms) <= slot_info[s]["in_person_room_capacity"], name=f"room_{s}")

    # Telehealth channel capacity
    th_terms = {}
    for (pi, v, s, m) in eligible:
        if m == "telehealth":
            th_terms.setdefault(s, []).append(x[(pi, v, s, m)])
    for s, terms in th_terms.items():
        model.addCons(quicksum(terms) <= slot_info[s]["telehealth_channel_capacity"], name=f"channel_{s}")

    # Exam room capacity
    exam_terms = {}
    for (pi, v, s, m) in eligible:
        if type_info[pat_info[pi]["appointment_type"]]["requires_exam_room"]:
            exam_terms.setdefault(s, []).append(x[(pi, v, s, m)])
    for s, terms in exam_terms.items():
        model.addCons(quicksum(terms) <= slot_info[s]["exam_room_capacity"], name=f"exam_{s}")

    obj_expr = quicksum(cost[k] * x[k] for k in x)
    model.setObjective(obj_expr, sense="minimize")

    model.optimize()

    status = model.getStatus()
    nsols = model.getNSols()
    objval = model.getObjVal() if nsols > 0 else None
    print(f"Status: {status}, NSols: {nsols}, ObjVal: {objval}")

    solution = {}
    if nsols > 0:
        sol = model.getBestSol()
        for k, var in x.items():
            val = model.getVal(var)
            if val > 0.5:
                pi, v, s, m = k
                solution[pat_info[pi]["patient_id"]] = (v, s, m)

    # Validate
    tol = 1e-5
    errors = []
    if len(solution) != len(pat_info):
        errors.append(f"Expected {len(pat_info)} assignments, got {len(solution)}")

    # provider-slot usage
    ps_use = {}
    pd_use = {}
    room_use = {}
    chan_use = {}
    exam_use = {}
    for pid, (v, s, m) in solution.items():
        ps_use[(v, s)] = ps_use.get((v, s), 0) + 1
        d = slot_info[s]["day"]
        pd_use[(v, d)] = pd_use.get((v, d), 0) + 1
        if m == "in_person":
            room_use[s] = room_use.get(s, 0) + 1
        else:
            chan_use[s] = chan_use.get(s, 0) + 1
        # find patient
        p = next(pp for pp in pat_info if pp["patient_id"] == pid)
        if type_info[p["appointment_type"]]["requires_exam_room"]:
            exam_use[s] = exam_use.get(s, 0) + 1
        # checks
        if v not in prov_info:
            errors.append(f"Unknown provider {v}")
        if prov_info[v]["specialty"] != p["specialty"]:
            errors.append(f"{pid}: specialty mismatch {v}")
        if not (slot_info[p["earliest_slot"]]["slot_index"] <= slot_info[s]["slot_index"] <= slot_info[p["due_slot"]]["slot_index"]):
            errors.append(f"{pid}: slot {s} outside window")
        if not avail.get((v, s), False):
            errors.append(f"{pid}: provider {v} unavailable at {s}")
        if m not in p["allowed_modes"]:
            errors.append(f"{pid}: mode {m} not allowed")
        if m == "telehealth":
            if not type_info[p["appointment_type"]]["telehealth_allowed"]:
                errors.append(f"{pid}: telehealth not allowed for type")
            if not prov_info[v]["telehealth_enabled"]:
                errors.append(f"{pid}: provider {v} no telehealth")
        else:
            if not prov_info[v]["in_person_enabled"]:
                errors.append(f"{pid}: provider {v} no in_person")
        if p["continuity_required"] and v != p["preferred_provider"]:
            errors.append(f"{pid}: continuity violation")

    for (v, s), cnt in ps_use.items():
        if cnt > 1:
            errors.append(f"Provider {v} double-booked at {s}")
    for (v, d), cnt in pd_use.items():
        if cnt > prov_info[v]["daily_slot_limit"]:
            errors.append(f"Provider {v} daily limit exceeded on {d}: {cnt}")
    for s, cnt in room_use.items():
        if cnt > slot_info[s]["in_person_room_capacity"]:
            errors.append(f"Room capacity exceeded at {s}: {cnt}")
    for s, cnt in chan_use.items():
        if cnt > slot_info[s]["telehealth_channel_capacity"]:
            errors.append(f"Channel capacity exceeded at {s}: {cnt}")
    for s, cnt in exam_use.items():
        if cnt > slot_info[s]["exam_room_capacity"]:
            errors.append(f"Exam capacity exceeded at {s}: {cnt}")

    if errors:
        print("Validation errors:")
        for e in errors:
            print(" -", e)
    else:
        print("Validation passed.")

    # Write solution
    with open(SOLUTION_PATH, "w", newline="") as f:
        w = csv.writer(f)
        w.writerow(["patient_id", "provider_id", "slot_id", "mode"])
        for p in pat_info:
            pid = p["patient_id"]
            if pid in solution:
                v, s, m = solution[pid]
                w.writerow([pid, v, s, m])
            else:
                w.writerow([pid, "", "", ""])

    print(f"Wrote {SOLUTION_PATH}")

if __name__ == "__main__":
    main()
